      failed++;
      console.log(`FAIL ${f}:`);
      for (const e of errs) console.log(`   ${e.message ?? JSON.stringify(e)}`);
    }
  } else {
    failed++;
    console.log(`FAIL ${f}: ${JSON.stringify(res)}`);
  }
}
process.exit(failed ? 1 : 0);
EOF
